var trigger=root.querySelector('.ov5-modal-spring-trigger');
var card=root.querySelector('.ov5-modal-spring-card');
var scrim=root.querySelector('.ov5-modal-spring-scrim');
var isOpen=false;
function open(){if(isOpen)return;isOpen=true;root.classList.remove('ov5-modal-spring-shut');root.classList.add('ov5-modal-spring-open');trigger.setAttribute('aria-expanded','true');card.focus();}
function close(){if(!isOpen)return;isOpen=false;root.classList.remove('ov5-modal-spring-open');root.classList.add('ov5-modal-spring-shut');trigger.setAttribute('aria-expanded','false');trigger.focus();}
card.addEventListener('animationend',function(e){if(e.animationName==='ov5-modal-spring-drop'){root.classList.remove('ov5-modal-spring-shut');}});
trigger.addEventListener('click',open);
scrim.addEventListener('click',close);
root.querySelector('.ov5-modal-spring-cancel').addEventListener('click',close);
root.querySelector('.ov5-modal-spring-go').addEventListener('click',function(){close();trigger.textContent='Deleted — undo';});
root.addEventListener('keydown',function(e){
  if(!isOpen)return;
  if(e.key==='Escape'){e.preventDefault();close();return;}
  if(e.key==='Tab'){
    var f=root.querySelectorAll('.ov5-modal-spring-cancel,.ov5-modal-spring-go');
    var first=f[0],last=f[f.length-1];
    if(e.shiftKey&&(root.contains(document.activeElement)===false||document.activeElement===first||document.activeElement===card)){e.preventDefault();last.focus();}
    else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}
  }
});

