var toggle=root.querySelector('.ov5-side-drawer-toggle');
var panel=root.querySelector('.ov5-side-drawer-panel');
var scrim=root.querySelector('.ov5-side-drawer-scrim');
var items=root.querySelectorAll('.ov5-side-drawer-item');
var i;for(i=0;i<items.length;i++){items[i].tabIndex=-1;}
function set(open){
  root.classList.toggle('ov5-side-drawer-open',open);
  toggle.setAttribute('aria-expanded',open?'true':'false');
  toggle.setAttribute('aria-label',open?'Close menu':'Open menu');
  panel.setAttribute('aria-hidden',open?'false':'true');
  for(var k=0;k<items.length;k++){items[k].tabIndex=open?0:-1;}
  if(open){setTimeout(function(){items[0].focus();},140);}else{toggle.focus();}
}
toggle.addEventListener('click',function(){set(!root.classList.contains('ov5-side-drawer-open'));});
scrim.addEventListener('click',function(){set(false);});
root.addEventListener('keydown',function(e){if(e.key==='Escape'&&root.classList.contains('ov5-side-drawer-open')){e.preventDefault();set(false);}});

