var sheet=root.querySelector('.ov5-bottom-sheet-sheet');
var trigger=root.querySelector('.ov5-bottom-sheet-trigger');
var scrim=root.querySelector('.ov5-bottom-sheet-scrim');
var dragging=false,startY=0,lastY=0,lastT=0,dy=0,vel=0,pid=null;
function glide(on){sheet.classList.toggle('ov5-bottom-sheet-glide',on);}
function open(){glide(true);sheet.style.transform='';root.classList.add('ov5-bottom-sheet-open');trigger.setAttribute('aria-expanded','true');sheet.focus();}
function close(){glide(true);sheet.style.transform='';root.classList.remove('ov5-bottom-sheet-open');trigger.setAttribute('aria-expanded','false');trigger.focus();}
trigger.addEventListener('click',open);
scrim.addEventListener('click',close);
sheet.addEventListener('pointerdown',function(e){
  if(!root.classList.contains('ov5-bottom-sheet-open'))return;
  dragging=true;pid=e.pointerId;startY=lastY=e.clientY;lastT=e.timeStamp;dy=0;vel=0;
  glide(false);sheet.classList.add('ov5-bottom-sheet-drag');
  try{sheet.setPointerCapture(pid);}catch(err){}
});
sheet.addEventListener('pointermove',function(e){
  if(!dragging)return;
  dy=Math.max(0,e.clientY-startY);
  var dt=e.timeStamp-lastT;
  if(dt>0){vel=(e.clientY-lastY)/dt;lastY=e.clientY;lastT=e.timeStamp;}
  sheet.style.transform='translateY('+dy.toFixed(1)+'px)';
  scrim.style.opacity=String(Math.max(0,1-dy/110));
});
function release(){
  if(!dragging)return;dragging=false;
  sheet.classList.remove('ov5-bottom-sheet-drag');
  if(pid!==null){try{sheet.releasePointerCapture(pid);}catch(err){}pid=null;}
  scrim.style.opacity='';
  if(dy>46||vel>0.55){close();}else{glide(true);sheet.style.transform='translateY(0px)';}
}
sheet.addEventListener('pointerup',release);
sheet.addEventListener('pointercancel',release);
root.addEventListener('keydown',function(e){if(e.key==='Escape'&&root.classList.contains('ov5-bottom-sheet-open')){e.preventDefault();close();}});

