var trigger=root.querySelector('.ov5-arrow-popover-trigger');
var pop=root.querySelector('.ov5-arrow-popover-pop');
function place(){
  var t=trigger.getBoundingClientRect();
  var need=pop.offsetHeight+14;
  root.classList.toggle('ov5-arrow-popover-below',t.top<need&&(window.innerHeight-t.bottom)>need);
}
function set(on){
  if(on)place();
  root.classList.toggle('ov5-arrow-popover-on',on);
  trigger.setAttribute('aria-expanded',on?'true':'false');
}
trigger.addEventListener('click',function(e){e.stopPropagation();set(!root.classList.contains('ov5-arrow-popover-on'));});
root.addEventListener('keydown',function(e){if(e.key==='Escape'&&root.classList.contains('ov5-arrow-popover-on')){e.preventDefault();set(false);trigger.focus();}});
root.addEventListener('focusout',function(e){if(!root.contains(e.relatedTarget))set(false);});
document.addEventListener('click',function(e){if(!root.contains(e.target))set(false);});

