function sample(x,y,w){
  var pct=Math.min(1,Math.max(0,x/w));
  var ms=Math.round(180+pct*40+Math.sin(pct*7)*90+120*pct);
  var mins=Math.round(pct*23*60);
  var hh=String(Math.floor(mins/60)).padStart(2,'0'),mm=String(Math.floor(mins%60/10)*10).padStart(2,'0');
  val.textContent=ms+' ms';sub.textContent=hh+':'+mm+' · eu-west-1';
