var DATA=[{t:'Deploy to production',g:'↑',k:'Ship'},{t:'Revert last release',g:'↺',k:'Git'},{t:'Invite teammate',g:'+',k:'Team'},{t:'Rotate API keys',g:'⚙',k:'Security'},{t:'Open runtime logs',g:'≡',k:'Debug'},{t:'Pause all cron jobs',g:'⏸',k:'Jobs'}];
var input=root.querySelector('.ov5-cmd-palette-input');
var list=root.querySelector('.ov5-cmd-palette-list');
var empty=root.querySelector('.ov5-cmd-palette-empty');
var qspan=root.querySelector('.ov5-cmd-palette-q');
var toast=root.querySelector('.ov5-cmd-palette-toast');
var rows=[],sel=0,tid=0;
function score(text,q){
  if(!q)return{s:0,hits:[]};
  var lt=text.toLowerCase(),lq=q.toLowerCase(),hits=[],i=0,s=0,prev=-2;
  for(var j=0;j<lq.length;j++){
    if(lq[j]===' ')continue;
    var f=lt.indexOf(lq[j],i);
    if(f<0)return null;
    s+=(f===prev+1?3:1)+(f===0||lt[f-1]===' '?2:0);
    hits.push(f);prev=f;i=f+1;
  }
  return{s:s,hits:hits};
}
function mark(text,hits){
  var out='',h=0;
  for(var i=0;i<text.length;i++){
    var c=text[i].replace('&','&amp;').replace('<','&lt;');
    if(hits[h]===i){out+='<span class="ov5-cmd-palette-hit">'+c+'</span>';h++;}else{out+=c;}
  }
  return out;
}
function render(){
  var q=input.value.trim();
  var out=[];
  for(var i=0;i<DATA.length;i++){var r=score(DATA[i].t,q);if(r)out.push({d:DATA[i],r:r});}
  out.sort(function(a,b){return b.r.s-a.r.s;});
  out=out.slice(0,4);
  list.innerHTML='';
  rows=[];sel=0;
  empty.hidden=out.length>0;
  qspan.textContent=q?'“'+q+'”':'';
  for(var k=0;k<out.length;k++){
    var li=document.createElement('li');
    li.className='ov5-cmd-palette-opt';
    li.setAttribute('role','option');
    li.setAttribute('aria-selected',k===0?'true':'false');
    li.innerHTML='<span class="ov5-cmd-palette-ico">'+out[k].d.g+'</span><span class="ov5-cmd-palette-label">'+mark(out[k].d.t,out[k].r.hits)+'</span><span class="ov5-cmd-palette-tag">'+out[k].d.k+'</span>';
    li.setAttribute('data-run',out[k].d.t);
    (function(el){el.addEventListener('click',function(){run(el);});el.addEventListener('pointerenter',function(){move(rows.indexOf(el)-sel);});})(li);
    list.appendChild(li);rows.push(li);
  }
  paint();
}
function paint(){for(var i=0;i<rows.length;i++){var on=i===sel;rows[i].classList.toggle('ov5-cmd-palette-sel',on);rows[i].setAttribute('aria-selected',on?'true':'false');}}
function move(d){if(!rows.length)return;sel=(sel+d+rows.length)%rows.length;paint();}
function run(el){
  if(!el)return;
  toast.textContent='Running “'+el.getAttribute('data-run')+'”…';
  toast.classList.add('ov5-cmd-palette-toast-on');
  clearTimeout(tid);tid=setTimeout(function(){toast.classList.remove('ov5-cmd-palette-toast-on');},1800);
}
input.addEventListener('input',render);
input.addEventListener('keydown',function(e){
  if(e.key==='ArrowDown'){e.preventDefault();move(1);}
  else if(e.key==='ArrowUp'){e.preventDefault();move(-1);}
  else if(e.key==='Enter'){e.preventDefault();run(rows[sel]);}
  else if(e.key==='Escape'){e.preventDefault();input.value='';render();}
});
render();

