function show(i){
  idx=(i+thumbs.length)%thumbs.length;
  fill.style.backgroundImage=thumbs[idx].getAttribute('data-art');
  cap.textContent=thumbs[idx].getAttribute('data-cap')+'  ·  '+(idx+1)+' / '+thumbs.length;
