var WORD='DESTROY';
var input=root.querySelector('.ov5-type-confirm-input');
var bar=root.querySelector('.ov5-type-confirm-fillbar');
var go=root.querySelector('.ov5-type-confirm-go');
var label=root.querySelector('.ov5-type-confirm-label');
var status=root.querySelector('.ov5-type-confirm-status');
var busy=false;
function check(){
  var v=input.value;
  var ok=0;
  for(var i=0;i<v.length&&i<WORD.length;i++){if(v[i].toUpperCase()===WORD[i])ok++;else break;}
  var armed=v.toUpperCase()===WORD;
  bar.style.width=Math.round(ok/WORD.length*100)+'%';
  root.classList.toggle('ov5-type-confirm-armed',armed);
  go.disabled=!armed;
  if(!busy){
    status.classList.toggle('ov5-type-confirm-bad',v.length>0&&ok<v.length);
    status.textContent=v.length>0&&ok<v.length?'That does not match':'7 nodes · 2 volumes';
  }
}
function shake(){
  root.classList.remove('ov5-type-confirm-shake');
  void root.offsetWidth;
  root.classList.add('ov5-type-confirm-shake');
}
function fire(){
  if(busy)return;
  if(input.value.toUpperCase()!==WORD){shake();input.focus();return;}
  busy=true;
  root.classList.add('ov5-type-confirm-busy');
  label.textContent='Destroying';
  status.classList.remove('ov5-type-confirm-bad');
  status.textContent='Draining 7 nodes…';
